		List<BindingSet> expected = evaluate(query, false);
		assertThat(expected).hasSize(1);
		assertThat(expected.get(0).getValue("cat").stringValue()).isEqualTo("outer");
		assertThat(((Literal) expected.get(0).getValue("total")).longValue()).isEqualTo(6L);
