	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void aProvedFullValueSerialAlternativeRemainsAvailableToALengthConsumer(boolean alias) {
		String input = GROUPED + (alias ? " BIND(?cat AS ?renamed)" : "");
		String name = alias ? "?renamed" : "?cat";
		String length = "SELECT (SUM(STRLEN(" + name + ")) AS ?total) WHERE { " + input + " }";
		String full = "SELECT (SUM(STRLEN(" + name + ")) AS ?total) WHERE { " + input
				+ " FILTER(isLiteral(" + name + ")) }";
		List<BindingSet> expected = evaluate(length, false);
		assertThat(evaluate(full, false)).containsExactlyElementsOf(expected);
		assertThat(evaluate(length, true)).containsExactlyElementsOf(expected);
		assertThat(explain(full)).contains("FULL_VALUE").doesNotContain("LEXICAL_LENGTH");
		assertThat(explain(length)).contains("LEXICAL_LENGTH");
		String route = "irAggregateInterpreted";
		for (String query : List.of(full, length)) {
			System.setProperty(NATIVE, "true");
			try (SailRepositoryConnection connection = repository.getConnection()) {
				SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
				prepared.setForcedLmdbExecutionStrategy(route);
				try (var rows = prepared.evaluate()) {
					assertThat(QueryResults.asList(rows)).containsExactlyElementsOf(expected);
				}
				SailTupleQuery telemetry = (SailTupleQuery) connection.prepareTupleQuery(query);
				telemetry.setForcedLmdbExecutionStrategy(route);
				List<String> paths = new ArrayList<>();
				collectActualPaths(telemetry.explain(Explanation.Level.Telemetry).toGenericPlanNode(), paths);
				assertThat(paths).as("the explicit FULL control must open before the identical length consumer")
						.contains(route);
			}
		}
	}

