	@Test
	void nestedOwnersFollowEachEntryOfAReusedPreparedQuery(@TempDir Path directory) throws Exception {
		String query = "SELECT (SUM(STRLEN(?cat)) AS ?total) WHERE { " + GROUPED + " }";
		List<BindingSet> expected = evaluate(query, false);
		System.setProperty(NATIVE, "true");
		AtomicLong firstThread = new AtomicLong(), secondThread = new AtomicLong();
		Path output = directory.resolve("reused-owner.jfr");
		try (Recording recording = new Recording();
				SailRepositoryConnection connection = repository.getConnection();
				ExecutorService first = Executors.newSingleThreadExecutor();
				ExecutorService second = Executors.newSingleThreadExecutor()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			recording.enable("org.eclipse.rdf4j.lmdb.NativeExecutionPhase").withThreshold(Duration.ZERO);
			recording.start();
			assertThat(first.submit(() -> {
				firstThread.set(Thread.currentThread().threadId());
				try (var rows = prepared.evaluate()) {
					return QueryResults.asList(rows);
				}
			}).get()).containsExactlyElementsOf(expected);
			assertThat(second.submit(() -> {
				secondThread.set(Thread.currentThread().threadId());
				try (var rows = prepared.evaluate()) {
					return QueryResults.asList(rows);
				}
			}).get()).containsExactlyElementsOf(expected);
			recording.stop();
			recording.dump(output);
		}
		assertThat(firstThread.get()).isNotEqualTo(secondThread.get());
		List<RecordedEvent> events = RecordingFile.readAllEvents(output)
				.stream()
				.filter(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase"))
				.toList();
		assertThat(events).isNotEmpty();
		Set<Long> expectedThreads = Set.of(firstThread.get(), secondThread.get());
		for (RecordedEvent event : events) {
			assertThat(event.getEventType().getField("ownerThreadId"))
					.as("nested evaluation and replay must retain an explicit owner from the current evaluation entry")
					.isNotNull();
			assertThat(event.getLong("ownerThreadId")).isIn(expectedThreads);
		}
		for (long owner : expectedThreads) {
			assertThat(events.stream()
					.filter(event -> event.getLong("ownerThreadId") == owner)
					.map(event -> event.getLong("evaluationId"))
					.distinct()
					.toList()).isNotEmpty();
		}
		Set<Long> firstOwners = events.stream()
				.filter(event -> event.getLong("ownerThreadId") == firstThread.get())
				.map(event -> event.getLong("evaluationId"))
				.collect(Collectors.toSet());
		assertThat(events.stream()
				.filter(event -> event.getLong("ownerThreadId") == secondThread.get())
				.map(event -> event.getLong("evaluationId"))
				.toList()).doesNotContainAnyElementsOf(firstOwners);
	}

	private static void collectActualPaths(GenericPlanNode node, List<String> paths) {
		String actual = node.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		if (actual != null) {
			paths.add(actual);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectActualPaths(child, paths);
			}
		}
	}

	private static void assertPhysicalGroupInventory(GenericPlanNode node) {
		String actual = node.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		if (node.getType().startsWith("Group") && actual != null) {
			// StrategyDecision is deliberately an Optimized-only public report. Telemetry's local legal
			// inventory is the plan-owned estimated quote list produced from the same offered candidates.
			String quoted = node.getStringMetricActual(NativeAggregateCostQuotes.METRIC);
			assertThat(quoted).as("each physical group must publish its own offered candidate quotes").isNotNull();
			List<String> legal = new ArrayList<>();
			var candidates = Pattern.compile("\"strategy\":\"([^\"]+)\"").matcher(quoted);
			while (candidates.find()) {
				legal.add(candidates.group(1));
			}
			assertThat(legal).as("the physical group route %s must belong to its common legal inventory", actual)
					.contains(actual);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				assertPhysicalGroupInventory(child);
			}
		}
	}

	private List<BindingSet> evaluate(String query, boolean nativeEnabled) {
		System.setProperty(NATIVE, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection();
				var result = connection.prepareTupleQuery(query).evaluate()) {
			return QueryResults.asList(result);
		}
	}

	private String explain(String query) {
		System.setProperty(NATIVE, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString();
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = new ArrayList<>();
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>();
			row.forEach(binding -> {
				Value value = binding.getValue();
				if (binding.getName().equals("cat")) {
					assertThat(value).isInstanceOf(Literal.class);
					Literal literal = (Literal) value;
					assertThat(literal.getDatatype()).isEqualTo(XSD.STRING);
					List<String> members = new ArrayList<>(List.of(literal.getLabel().split(Pattern.quote("😀|"), -1)));
					members.sort(String::compareTo);
					bindings.add("cat=" + members);
				} else {
					bindings.add(binding.getName() + '=' + value);
				}
			});
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		return result;
	}
